#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float3 amzp_position;
uniform float amzp_progressc;
uniform float amzp_progressd;
uniform float amzp_progresse;
uniform float amzp_progressa;
uniform float amzp_progressb;
uniform float amzp_alpha;
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color3;
layout(color) uniform half4 amzp_color4;
uniform float amzp_blendMode;



const float PI = 3.14159265359;
const float3 suncolor = float3(0.643,0.494,0.867);

float getSun(float2 uv){ return (length(uv) < 0.009) ? 1.0 : 0.0; }

float3 lensflares(float2 uv, float2 amzLocal_pos, out float3 sunflare, out float3 lensflare){
    float2 main = uv - amzLocal_pos;
    float2 uvd = uv * (length(uv));

    float ang = atan(main.y, main.x);
    float dist = length(main);
    dist = pow(dist, 0.1);

    float f0 = 1.0 / (length(uv - amzLocal_pos) * 25.0 + 1.0);
    f0 = pow(f0, 2.0);
    f0 = f0 + f0 * (sin((ang + 1.0/18.0) * 12.0) * 0.1 + dist * 0.1 + 0.8);

    float f2  = max(1.0/(1.0 + 32.0*pow(length(uvd + 0.8*amzLocal_pos),  2.0)), 0.0) * 0.25;
    float f22 = max(1.0/(1.0 + 32.0*pow(length(uvd + 0.85*amzLocal_pos), 2.0)), 0.0) * 0.23;
    float f23 = max(1.0/(1.0 + 32.0*pow(length(uvd + 0.9*amzLocal_pos),  2.0)), 0.0) * 0.21;

    float2 uvx = mix(uv, uvd, -0.5);
    float f4  = max(0.01 - pow(length(uvx + 0.4*amzLocal_pos),  2.4), 0.0) * 6.0;
    float f42 = max(0.01 - pow(length(uvx + 0.45*amzLocal_pos), 2.4), 0.0) * 5.0;
    float f43 = max(0.01 - pow(length(uvx + 0.5*amzLocal_pos),  2.4), 0.0) * 3.0;

    uvx = mix(uv, uvd, -0.4);
    float f5  = max(0.01 - pow(length(uvx + 0.2*amzLocal_pos),  5.5), 0.0) * 2.0;
    float f52 = max(0.01 - pow(length(uvx + 0.4*amzLocal_pos),  5.5), 0.0) * 2.0;
    float f53 = max(0.01 - pow(length(uvx + 0.6*amzLocal_pos),  5.5), 0.0) * 2.0;

    uvx = mix(uv, uvd, -0.5);
    float f6  = max(0.01 - pow(length(uvx - 0.3*amzLocal_pos), 1.6), 0.0) * 6.0;
    float f62 = max(0.01 - pow(length(uvx - 0.325*amzLocal_pos),1.6), 0.0) * 3.0;
    float f63 = max(0.01 - pow(length(uvx - 0.35*amzLocal_pos), 1.6), 0.0) * 5.0;

    sunflare = float3(f0);
    lensflare = float3(f2+f4+f5+f6, f22+f42+f52+f62, f23+f43+f53+f63);
    return sunflare + lensflare;
}

float3 anflares1(float2 uv, float intensity, float stretch, float brightness){
    uv.x *= 1.0 / max(intensity*stretch, 1e-3);
    uv.y *= 0.5;
    return float3(smoothstep(0.009, 0.0, length(uv))) * brightness;
}

float3 anflares2(float2 uv, float threshold, float intensity, float stretch, float brightness){
    threshold = 1.0 - threshold;
    float3 hdr = float3(getSun(uv));
    hdr = float3(floor(threshold + pow(hdr.r, 1.0)));
    float d = max(intensity, 1e-3);
    float c = max(intensity * stretch, 0.0);
    const int STEPS = 64;
    for (int k = 0; k <= STEPS; k++){
        float i = float(k) * (c / float(STEPS));
        float texL = getSun(uv + float2(i/d, 0.0));
        float texR = getSun(uv - float2(i/d, 0.0));
        float w = (c > 0.0) ? (1.0 - i / c) : 0.0;
        hdr += floor(threshold + pow(max(texL, texR), 4.0)) * max(w, 0.0);
    }
    return hdr * brightness;
}

float3 applyBlend(float3 base, float3 over, float a, int mode){
    float3 outc = base;
    if (mode == 0){ 
        outc = mix(base, over, a);
    } else if (mode == 1){ 
        outc = mix(base, base * over, a);
    } else if (mode == 2){ 
        float3 amzLocal_screen = 1.0 - (1.0 - base) * (1.0 - over);
        outc = mix(base, amzLocal_screen, a);
    }
    return outc;
}

void amzRender(){
    float2 R = screen.zw;
    float2 uv = amzScreenNorm() - 0.5;
    uv.x *= R.x / max(R.y, 1.0);


    float2 pos01 = clamp(float2(amzp_position.x, amzp_position.y) / 100.0, 0.0, 1.0);
    float2 mouse = pos01 - 0.5;
    mouse.x *= R.x / max(R.y, 1.0);


    mouse += float2(amzp_progressc * 0.05, amzp_progressd * 0.05);

    float3 col = float3(0.0);

    float3 sun, sunflare, lensflare;
    float3 flare = lensflares(uv * 1.5, mouse * 1.5, sunflare, lensflare);


    float3 anflare = pow(anflares2(uv - mouse, 0.5, 400.0, 0.9, 0.1), float3(4.0));

    float3 tint1 = amzp_color1.rgb;
    float3 tintBase = amzp_color3.rgb;
    float3 tintSec = amzp_color4.rgb;

    float refl = amzp_progressa;      
    float lumin = amzp_progressb;     
    float Strength = amzp_progresse;  

    float3 flareCol = (flare + anflare) * suncolor * 2.0;
    flareCol *= lumin;
    flareCol = mix(flareCol, flareCol * tint1, 0.6);
    flareCol += sunflare * tintBase * 0.5;
    flareCol += lensflare * tintSec * 0.25 * refl;

    float3 src = amzTexture(0, amzScreenNorm()).rgb;


    flareCol = pow(max(flareCol, 0.0), float3(1.0/2.2));

    float a = clamp(amzp_alpha * Strength, 0.0, 1.0);

    float bmode = float(int(amzp_blendMode));
    float wN = 1.0 - step(0.5, abs(bmode - 0.0)); 
    float wM = 1.0 - step(0.5, abs(bmode - 1.0)); 
    float wS = 1.0 - step(0.5, abs(bmode - 2.0)); 

    float3 colNormal   = mix(src, flareCol, a);
    float3 colMultiply = mix(src, src * flareCol, a);
    float3 screenMix   = 1.0 - (1.0 - src) * (1.0 - flareCol);
    float3 colScreen   = mix(src, screenMix, a);

    float3 outc = colNormal * wN + colMultiply * wM + colScreen * wS;
    amzOutput = float4(outc, 1.0);
}

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

